{
  "template": "trigger"
}

attribute "tsugumi";
namespace bcg;
table Trials { value:string; }
table Outputs { trials:Trials (required, tsugumi: "file"); }
root_type Outputs;

{ pkgs, inputs, params }:
{
  run = inputs.tsugumi.rCard { src = ./src; packages = ps: [ ps.metafor ]; };
}

{
  "language": "r",
  "inputs": [
    {
      "name": "start"
    }
  ],
  "retainArtifact": true,
  "artifactOutput": "trials",
  "filesystem": true
}

{
  "template": "fork",
  "params": [
    {
      "name": "branches",
      "type": "string[]",
      "data": [
        "pool",
        "funnel",
        "moderator",
        "sensitivity"
      ]
    }
  ]
}

attribute "tsugumi";
namespace bcg;
table Pooled { value:string; }
table Outputs { pooled:Pooled (required, tsugumi: "file"); }
root_type Outputs;

{ pkgs, inputs, params }:
{
  run = inputs.tsugumi.rCard { src = ./src; packages = ps: [ ps.metafor ]; };
}

{
  "language": "r",
  "inputs": [
    {
      "name": "trials"
    }
  ],
  "retainArtifact": true,
  "artifactOutput": "pooled",
  "filesystem": true,
  "params": [
    {
      "name": "method",
      "type": "string",
      "data": "DL"
    },
    {
      "name": "exclude",
      "type": "uint64[]",
      "data": []
    }
  ]
}

{ pkgs, inputs, params }:
{
  run = inputs.tsugumi.rCard { src = ./src; packages = ps: [ ps.metafor ]; };
}

{
  "language": "r",
  "inputs": [
    {
      "name": "trials"
    }
  ],
  "params": [
    {
      "name": "method",
      "type": "string",
      "data": "DL"
    }
  ]
}

attribute "tsugumi";
namespace bcg;
table Regression { value:string; }
table Outputs { regression:Regression (required, tsugumi: "file"); }
root_type Outputs;

{ pkgs, inputs, params }:
{
  run = inputs.tsugumi.rCard { src = ./src; packages = ps: [ ps.metafor ps.ggplot2 ps.ggrepel ]; };
}

{
  "language": "r",
  "inputs": [
    {
      "name": "trials"
    }
  ],
  "retainArtifact": true,
  "artifactOutput": "regression",
  "filesystem": true,
  "params": [
    {
      "name": "moderator",
      "type": "string",
      "data": "ablat"
    },
    {
      "name": "method",
      "type": "string",
      "data": "REML"
    }
  ]
}

attribute "tsugumi";
namespace bcg;
table Sensitivity { value:string; }
table Outputs { sensitivity:Sensitivity (required, tsugumi: "file"); }
root_type Outputs;

{ pkgs, inputs, params }:
{
  run = inputs.tsugumi.rCard { src = ./src; packages = ps: [ ps.metafor ps.ggplot2 ]; };
}

{
  "language": "r",
  "inputs": [
    {
      "name": "trials"
    }
  ],
  "retainArtifact": true,
  "artifactOutput": "sensitivity",
  "filesystem": true,
  "params": [
    {
      "name": "estimators",
      "type": "string[]",
      "data": [
        "DL",
        "HE",
        "HS",
        "SJ",
        "ML",
        "REML",
        "PM"
      ]
    }
  ]
}
